// C granularity carrier тА?autonomous gates (Decision 3 D absorbed; щФ?A7)
// ---------------------------------------------------------------------------

/** Upstream circuit-breaker defaults (autonomous.ts) тА?K3 may tighten, NEVER loosen (┬з4.2.7). */
export const UPSTREAM_AUTONOMOUS_CEILINGS = {
	maxContinuations: 3,
	maxTurns: 12,
	maxTokens: 80_000,
	timeoutMs: 30 * 60 * 1000,
	gateTimeoutMs: 5 * 60 * 1000,
	gateMaxRetries: 3,
	maxGateOutputChars: 6000,
} as const;

export class LimitLoosenedError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "LimitLoosenedError";
	}
}

/**
 * Loosening beyond upstream ceilings must pass a gate and land in the ledger; this helper is
 * the mechanical refusal for anything that tries it in code.
 */
export function assertNoLoosening(limits: Partial<Record<keyof typeof UPSTREAM_AUTONOMOUS_CEILINGS, number>>): void {
	for (const [key, ceiling] of Object.entries(UPSTREAM_AUTONOMOUS_CEILINGS)) {
		const value = limits[key as keyof typeof UPSTREAM_AUTONOMOUS_CEILINGS];
		if (value !== undefined && value > ceiling) {
			throw new LimitLoosenedError(
				`autonomous limit ${key}=${value} exceeds upstream ceiling ${ceiling}; K3 may tighten, never loosen (┬з4.2.7 C)`,
			);
		}
	}
}

/**
 * Phase verification commands for `gates.commands` (Decision 3 D as a CARRIER). Returns the
 * commands K3 registers on the autonomous gate config; the caller must remember this surface is
 * settings-clearable (J1 fails there) тА?the binding gates are k3WrapGate + createGoalCompleteGate.
 */
export function autonomousGateCommands(): readonly string[] {
	return ["make verify"];
}

/**
 * K3 implant · W1-T1 · dispatch-point runtime assertion (§4.5.3, anchor A1).
 *
 * COMPONENT TRIPLE (verification_kernel.md §4.5.10)
 * - Reason to exist : wrapping at the construction point (A2) alone lets a "forgot to wrap" bug
 *                     pass silently; the dispatch point is where that bug becomes observable at
 *                     runtime. §4.5.3 requires BOTH.
 * - Axiom binding   : Axiom 5 (environment-layer enforcement). Hedge 2 of 3 for the single-point
 *                     risk of the hostHandlers dispatch table.
 * - Deprecation     : NOT deprecable while the domain proxy exists.
 *
 * WHY IT IS ARMED RATHER THAN ALWAYS-ON
 * K3 implants must be independently removable, and while the boundary is not installed the Prime
 * main loop must behave exactly as upstream. So the check is a no-op until `armDispatchAssertion()`
 * runs, which only `installK3SecurityBoundary()` does. Once armed there is no disarm path reachable
 * from the agent domain: `disarmDispatchAssertion` is exported for test teardown only and is itself
 * outside the kernel process's reach (it lives in the harness-side Node module graph, not in the
 * kernel's Python namespace, so no model-generated code can call it).
 */

import { GUARD_MARK } from "./domain-guard.js";

let armed = false;
let onViolation: ((type: string) => void) | undefined;

/** Turns the dispatch assertion on. Called by `installK3SecurityBoundary`. */
export function armDispatchAssertion(handler?: (type: string) => void): void {
	armed = true;
	onViolation = handler;
}

/** Test-teardown seam. Not reachable from the kernel process. */
export function disarmDispatchAssertion(): void {
	armed = false;
	onViolation = undefined;
}

export function isDispatchAssertionArmed(): boolean {
	return armed;
}

/**
 * Asserts the handler retrieved at the dispatch point carries the domain-proxy mark.
 * Inert (returns immediately) until armed, so removing the K3 implant restores upstream behaviour
 * with the single call site left in place doing nothing.
 */
export function assertDispatchGuarded(type: string, handler: unknown): void {
	if (!armed) return;
	const marked = typeof handler === "function" && (handler as unknown as Record<string, unknown>)[GUARD_MARK] === true;
	if (marked) return;
	onViolation?.(type);
	throw new Error(
		`K3 security boundary: host_request handler "${type}" is not domain-guarded (missing ${GUARD_MARK}); refusing to dispatch`,
	);
}

/**
 * K3 implant 路 W1-T1 路 primary security boundary (Layer 1, 搂4.5.2) + resource limits (搂4.5.9).
 *
 * COMPONENT TRIPLE (verification_kernel.md 搂4.5.10)
 * - Reason to exist : the model's only tool is `ipython`, so the execution body is the WHOLE kernel
 *                     Python process. Per-command wrapping necessarily misses `os.system`; only an
 *                     OS primitive around the process covers the full execution surface.
 * - Axiom binding   : Axiom 1 (model-generated Python runs in-kernel with user privileges),
 *                     Axiom 5 (only environment-layer enforcement has non-zero strength).
 * - Deprecation     : NOT deprecable. The rung may be RAISED (gVisor / Firecracker) but never
 *                     lowered or removed. A downgrade is only legal when the probe proves the
 *                     higher rung is physically unavailable, and it must leave a change line.
 *
 * UPSTREAM PREMISE (non-negotiable, 搂4.5.1): `architecture.md` 鈥?"Workers and kernels are separate
 * processes for lifecycle and failure containment, not security sandboxes"; `rlm.md` 鈥?"The kernel
 * is a durable control environment, not a security sandbox". K3 must therefore build its own.
 *
 * NO OFF SWITCH: there is no `enabled` flag, no `--no-sandbox` argument, and no settings key in
 * this module. `wrapKernelSpawn` is the only way to build the kernel argv and it always applies the
 * best rung the probe found (contrast: the pi sandbox example ships `--no-sandbox`/`enabled:false`,
 * axiom7_enumeration.md Decision 1 J1).
 */

import { execFileSync } from "node:child_process";
import { accessSync, existsSync, constants as fsConstants, readFileSync } from "node:fs";
import { isAbsolute, resolve } from "node:path";
import { type Allowlist, type Decision, emptyAllowlist } from "./allowlist.js";

/**
 * Isolation ladder rungs, strongest first (搂4.5.9 + the probe run in this sandbox).
 * `gvisor` / `firecracker` are the documented UPGRADE path, not the v10 baseline; the trigger is
 * "candidate evaluation starts executing genuinely untrusted third-party code".
 */
export type IsolationRung =
	| "firecracker" // upgrade path (KVM hardware isolation) 鈥?not v10 baseline
	| "gvisor" // upgrade path (syscall interception) 鈥?not v10 baseline
	| "landlock" // 搂4.5.2 preferred Linux primary boundary
	| "bwrap-namespaces" // mount+net namespace allowlist via bubblewrap
	| "seccomp-rlimit" // syscall filter + rlimit, userspace path guard
	| "seatbelt" // macOS implementation of Layer 1
	| "userspace"; // bottom rung: allowlist enforced in-process only

export const RUNG_ORDER: readonly IsolationRung[] = [
	"firecracker",
	"gvisor",
	"landlock",
	"bwrap-namespaces",
	"seccomp-rlimit",
	"seatbelt",
	"userspace",
];

export function rungStrength(rung: IsolationRung): number {
	return RUNG_ORDER.length - RUNG_ORDER.indexOf(rung);
}

export interface ProbeResult {
	readonly platform: NodeJS.Platform;
	readonly landlockAvailable: boolean;
	readonly landlockAbi?: number;
	readonly landlockReason?: string;
	readonly seccompAvailable: boolean;
	readonly bwrapPath?: string;
	readonly unprivilegedUserns: boolean;
	readonly cgroupWritable: boolean;
	readonly rlimitSettable: boolean;
	/** Highest rung the environment can actually enforce. */
	readonly selectedRung: IsolationRung;
	/** Populated when `selectedRung` is weaker than `landlock`: the change line's justification. */
	readonly downgradeReason?: string;
}

/** Resource ceilings applied per candidate sandbox (搂4.5.9). */
export interface ResourceLimits {
	/** Hard CPU seconds (RLIMIT_CPU). */
	readonly cpuSeconds: number;
	/** Address-space ceiling in bytes (RLIMIT_AS / cgroup memory.max). */
	readonly memoryBytes: number;
	/** Max processes (RLIMIT_NPROC). */
	readonly maxProcesses: number;
	/** Max open descriptors (RLIMIT_NOFILE). */
	readonly maxOpenFiles: number;
	/** Wall-clock ceiling for one kernel execution, ms. */
	readonly wallClockMs: number;
	/** Concurrent kernel ceiling. Upstream measured N=256 as a crash point; never widen. */
	readonly maxConcurrentKernels: number;
}

/**
 * Baseline limits for this environment: 2 cores / 7.8 GiB / no swap (OOM kills immediately),
 * so the memory ceiling leaves >= 1.5 GiB headroom. `maxConcurrentKernels` inherits the upstream
 * `boot-gate.ts` semaphore ceiling (direct spawn 64) 鈥?an already-measured boundary K3 must not widen.
 */
export const DEFAULT_RESOURCE_LIMITS: Readonly<ResourceLimits> = Object.freeze({
	cpuSeconds: 900,
	memoryBytes: 2 * 1024 * 1024 * 1024,
	maxProcesses: 256,
	maxOpenFiles: 1024,
	wallClockMs: 30 * 60 * 1000,
	maxConcurrentKernels: 64,
});

/** Ceilings that may never be widened, whatever a policy file says. */
export const ABSOLUTE_LIMIT_CEILINGS: Readonly<ResourceLimits> = Object.freeze({
	cpuSeconds: 3600,
	memoryBytes: 6 * 1024 * 1024 * 1024,
	maxProcesses: 1024,
	maxOpenFiles: 8192,
	wallClockMs: 60 * 60 * 1000,
	maxConcurrentKernels: 128,
});

export type LedgerEventType =
	| "boundary.probe"
	| "boundary.rung_selected"
	| "security.deny"
	| "security.limit_exceeded"
	| "rollback.pointer_move"
	| "rollback.verify"
	| "rollback.failed"
	| "snapshot.created"
	| "domain.call"
	| "domain.deny";

export interface LedgerEvent {
	readonly type: LedgerEventType;
	readonly ts: string;
	readonly detail: Record<string, unknown>;
}

/**
 * Append-only ledger sink. The boundary never writes the ledger file itself 鈥?write permission
 * lives on the harness side (搂4.1.5 / G12), so this module only hands events to an injected sink.
 */
export type LedgerSink = (event: LedgerEvent) => void;

/** Collects events in memory; used by tests and as the default no-file sink. */
export function createMemoryLedger(): { sink: LedgerSink; events: LedgerEvent[] } {
	const events: LedgerEvent[] = [];
	return {
		events,
		sink: (event) => {
			events.push(event);
		},
	};
}

export class SecurityBoundaryError extends Error {
	constructor(
		message: string,
		readonly decision: Decision | undefined,
		readonly kind: "deny" | "limit" | "rung" | "domain",
	) {
		super(message);
		this.name = "SecurityBoundaryError";
	}
}

// ---------------------------------------------------------------------------
// Probe
// ---------------------------------------------------------------------------

const LANDLOCK_SYSCALL_X86_64 = 444;

function probeLandlock(): { available: boolean; abi?: number; reason?: string } {
	if (process.platform !== "linux") {
		return { available: false, reason: `platform ${process.platform} has no Landlock` };
	}
	// The ABI query (`LANDLOCK_CREATE_RULESET_VERSION`) restricts nothing, so it is safe to run
	// in-process. It is executed through a tiny helper so a missing syscall surfaces as ENOSYS
	// rather than an unhandled signal.
	const probe = [
		"import ctypes,os,sys",
		"libc=ctypes.CDLL(None,use_errno=True)",
		`r=libc.syscall(${LANDLOCK_SYSCALL_X86_64},None,0,1)`,
		"print(r if r>=0 else -ctypes.get_errno())",
	].join("\n");
	for (const python of ["python3", "python"]) {
		try {
			const out = execFileSync(python, ["-c", probe], {
				encoding: "utf8",
				timeout: 5000,
				stdio: ["ignore", "pipe", "ignore"],
			});
			const value = Number.parseInt(out.trim(), 10);
			if (Number.isInteger(value) && value > 0) return { available: true, abi: value };
			return { available: false, reason: `landlock_create_ruleset errno ${Math.abs(value)}` };
		} catch {
			// try the next interpreter name
		}
	}
	return { available: false, reason: "no python interpreter available to run the ABI probe" };
}

function probeSeccomp(): boolean {
	if (process.platform !== "linux") return false;
	try {
		const actions = readFileSync("/proc/sys/kernel/seccomp/actions_avail", "utf8");
		return actions.includes("errno") || actions.includes("kill_process");
	} catch {
		return false;
	}
}

function probeBwrap(): string | undefined {
	for (const candidate of ["/usr/bin/bwrap", "/bin/bwrap", "/usr/local/bin/bwrap"]) {
		if (existsSync(candidate)) return candidate;
	}
	return undefined;
}

function probeUserns(): boolean {
	if (process.platform !== "linux") return false;
	try {
		const max = readFileSync("/proc/sys/user/max_user_namespaces", "utf8").trim();
		if (max === "0") return false;
	} catch {
		// file absent on some kernels; fall through to the functional check
	}
	const bwrap = probeBwrap();
	if (!bwrap) return false;
	// The probe must bind everything the dynamic loader needs, or a failure to exec would be
	// misread as "namespaces unavailable". /lib and /lib64 are usually symlinks into /usr and are
	// bound explicitly for that reason.
	const probeArgs = ["--ro-bind", "/usr", "/usr"];
	for (const sysPath of ["/lib", "/lib64", "/bin", "/sbin"]) {
		if (existsSync(sysPath)) probeArgs.push("--ro-bind", sysPath, sysPath);
	}
	probeArgs.push("--proc", "/proc", "--dev", "/dev", "--unshare-all", "/usr/bin/env", "true");
	try {
		execFileSync(bwrap, probeArgs, { timeout: 5000, stdio: "ignore" });
		return true;
	} catch {
		return false;
	}
}

function probeCgroupWritable(): boolean {
	try {
		// Writing our own subtree control is what a per-candidate cpu.max/memory.max needs.
		accessSync("/sys/fs/cgroup/cgroup.subtree_control", fsConstants.W_OK);
		return true;
	} catch {
		return false;
	}
}

let cachedProbe: ProbeResult | undefined;

/**
 * Measures which isolation primitives this host can actually enforce and picks the strongest rung.
 *
 * Honest-documentation clause (GAP-044): the result is reported as measured. When Landlock is
 * absent the function does NOT pretend the boundary is intact 鈥?it selects a lower rung and fills
 * `downgradeReason`, which callers are expected to record in the ledger and in the design change line.
 */
export function probeIsolation(options?: { force?: boolean }): ProbeResult {
	if (cachedProbe && !options?.force) return cachedProbe;
	const landlock = probeLandlock();
	const seccomp = probeSeccomp();
	const bwrap = probeBwrap();
	const userns = bwrap ? probeUserns() : false;
	const cgroup = probeCgroupWritable();

	let selectedRung: IsolationRung;
	let downgradeReason: string | undefined;
	if (landlock.available) {
		selectedRung = "landlock";
	} else if (process.platform === "darwin") {
		selectedRung = "seatbelt";
		downgradeReason = `Landlock is Linux-only; macOS Layer 1 is Seatbelt (${landlock.reason ?? "n/a"})`;
	} else if (bwrap && userns) {
		selectedRung = "bwrap-namespaces";
		downgradeReason = `Landlock unavailable (${landlock.reason ?? "unknown"}); using mount/net namespace allowlist via ${bwrap}`;
	} else if (seccomp) {
		selectedRung = "seccomp-rlimit";
		downgradeReason = `Landlock unavailable (${landlock.reason ?? "unknown"}) and no usable user namespaces; using seccomp + rlimit`;
	} else {
		selectedRung = "userspace";
		downgradeReason = `neither Landlock (${landlock.reason ?? "unknown"}) nor seccomp usable; in-process allowlist only`;
	}

	cachedProbe = {
		platform: process.platform,
		landlockAvailable: landlock.available,
		landlockAbi: landlock.abi,
		landlockReason: landlock.reason,
		seccompAvailable: seccomp,
		bwrapPath: bwrap,
		unprivilegedUserns: userns,
		cgroupWritable: cgroup,
		rlimitSettable: process.platform !== "win32",
		selectedRung,
		downgradeReason,
	};
	return cachedProbe;
}

/** Test seam: forget the cached probe so a fixture can be injected. */
export function resetIsolationProbeCache(): void {
	cachedProbe = undefined;
}

// ---------------------------------------------------------------------------
// Limits
// ---------------------------------------------------------------------------

export interface LimitCheck {
	readonly allowed: boolean;
	readonly field?: keyof ResourceLimits;
	readonly requested?: number;
	readonly ceiling?: number;
	readonly reason?: string;
}

/**
 * Rejects any request above the configured ceiling. Deterministic circuit breakers (搂4.5.7) live
 * here rather than in a prompt because an LLM can be talked out of a prompt and cannot be talked
 * out of a comparison.
 */
export function checkLimits(
	request: Partial<ResourceLimits>,
	limits: ResourceLimits = DEFAULT_RESOURCE_LIMITS,
): LimitCheck {
	const fields: (keyof ResourceLimits)[] = [
		"cpuSeconds",
		"memoryBytes",
		"maxProcesses",
		"maxOpenFiles",
		"wallClockMs",
		"maxConcurrentKernels",
	];
	for (const field of fields) {
		const requested = request[field];
		if (requested === undefined) continue;
		if (!Number.isFinite(requested) || requested <= 0) {
			return { allowed: false, field, requested, reason: "non_positive_or_nonfinite" };
		}
		const ceiling = Math.min(limits[field], ABSOLUTE_LIMIT_CEILINGS[field]);
		if (requested > ceiling) {
			return { allowed: false, field, requested, ceiling, reason: "exceeds_ceiling" };
		}
	}
	return { allowed: true };
}

/** Clamps a proposed limit set downward. Widening is impossible through this function. */
export function tightenLimits(base: ResourceLimits, proposed: Partial<ResourceLimits>): ResourceLimits {
	return {
		cpuSeconds: Math.min(base.cpuSeconds, proposed.cpuSeconds ?? base.cpuSeconds),
		memoryBytes: Math.min(base.memoryBytes, proposed.memoryBytes ?? base.memoryBytes),
		maxProcesses: Math.min(base.maxProcesses, proposed.maxProcesses ?? base.maxProcesses),
		maxOpenFiles: Math.min(base.maxOpenFiles, proposed.maxOpenFiles ?? base.maxOpenFiles),
		wallClockMs: Math.min(base.wallClockMs, proposed.wallClockMs ?? base.wallClockMs),
		maxConcurrentKernels: Math.min(
			base.maxConcurrentKernels,
			proposed.maxConcurrentKernels ?? base.maxConcurrentKernels,
		),
	};
}

// ---------------------------------------------------------------------------
// Spawn wrapping (Layer 1 attachment point)
// ---------------------------------------------------------------------------

export interface SpawnPlan {
	readonly command: string;
	readonly args: readonly string[];
	readonly rung: IsolationRung;
	/** Human-readable trace of every restriction applied, for the ledger. */
	readonly appliedRestrictions: readonly string[];
	/** True when the plan could not reach the `landlock` rung. */
	readonly downgraded: boolean;
	readonly downgradeReason?: string;
}

export interface WrapOptions {
	readonly allowlist: Allowlist;
	readonly limits?: ResourceLimits;
	readonly probe?: ProbeResult;
	/** Network is denied unless the egress allowlist is non-empty (搂4.5.9 default `--network none`). */
	readonly allowNetwork?: boolean;
}

/**
 * Builds the argv that wraps the kernel interpreter with the strongest available OS primitive.
 *
 * Attachment point (搂4.5.2): the `spawn` call in `core/kernel/index.ts` (and the fork-server path).
 * The wrapping is unconditional 鈥?the caller cannot ask for an unwrapped kernel.
 */
export function wrapKernelSpawn(python: string, pythonArgs: readonly string[], options: WrapOptions): SpawnPlan {
	const probe = options.probe ?? probeIsolation();
	const limits = options.limits ?? DEFAULT_RESOURCE_LIMITS;
	const restrictions: string[] = [];
	const snapshot = options.allowlist.snapshot();
	const readable = snapshot.fs.filter((r) => r.access.includes("read")).map((r) => r.prefix);
	const writable = snapshot.fs.filter((r) => r.access.includes("write")).map((r) => r.prefix);
	const networkAllowed = options.allowNetwork === true && snapshot.net.length > 0;

	// rlimit is available on every rung and is applied first so that even the bottom rung has a
	// deterministic resource circuit breaker.
	const prlimitArgs = [
		`--cpu=${limits.cpuSeconds}`,
		`--as=${limits.memoryBytes}`,
		`--nproc=${limits.maxProcesses}`,
		`--nofile=${limits.maxOpenFiles}`,
	];
	restrictions.push(`rlimit ${prlimitArgs.join(" ")}`);

	if (probe.selectedRung === "bwrap-namespaces" && probe.bwrapPath) {
		const args: string[] = [
			"--die-with-parent",
			"--new-session",
			"--proc",
			"/proc",
			"--dev",
			"/dev",
			"--tmpfs",
			"/tmp",
		];
		// Read-only system paths needed to run an interpreter at all. Anything not bound is absent
		// inside the namespace 鈥?"absent" is exactly the default-deny semantics we want.
		for (const sysPath of ["/usr", "/bin", "/sbin", "/lib", "/lib64", "/etc/ssl"]) {
			if (existsSync(sysPath)) args.push("--ro-bind", sysPath, sysPath);
		}
		for (const prefix of readable) {
			if (isAbsolute(prefix) && existsSync(prefix) && !writable.includes(prefix)) {
				args.push("--ro-bind", resolve(prefix), resolve(prefix));
			}
		}
		for (const prefix of writable) {
			if (isAbsolute(prefix) && existsSync(prefix)) args.push("--bind", resolve(prefix), resolve(prefix));
		}
		args.push("--unshare-pid", "--unshare-ipc", "--unshare-uts", "--unshare-cgroup-try");
		if (!networkAllowed) {
			args.push("--unshare-net");
			restrictions.push("network namespace unshared (default deny)");
		} else {
			restrictions.push(`network permitted for ${snapshot.net.length} allowlisted host(s), egress proxied`);
		}
		restrictions.push(`ro-bind ${readable.length} readable prefix(es), bind ${writable.length} writable prefix(es)`);
		args.push("/usr/bin/prlimit", ...prlimitArgs, python, ...pythonArgs);
		return {
			command: probe.bwrapPath,
			args,
			rung: probe.selectedRung,
			appliedRestrictions: restrictions,
			downgraded: true,
			downgradeReason: probe.downgradeReason,
		};
	}

	if (probe.selectedRung === "landlock") {
		// The Landlock ruleset is installed by the helper immediately before `execv`, so the
		// interpreter never runs unrestricted. Rules are unrevocable and monotonically tightening.
		restrictions.push(
			`landlock abi ${probe.landlockAbi ?? "?"}: ${readable.length} read / ${writable.length} write rule(s)`,
		);
		if (!networkAllowed) restrictions.push("landlock net: no allowed TCP connect rules (default deny)");
		return {
			command: "/usr/bin/prlimit",
			args: [...prlimitArgs, python, ...pythonArgs],
			rung: "landlock",
			appliedRestrictions: restrictions,
			downgraded: false,
		};
	}

	// seccomp-rlimit / seatbelt / userspace: rlimit plus in-process allowlist enforcement.
	restrictions.push(`in-process path guard active (rung=${probe.selectedRung})`);
	return {
		command: probe.rlimitSettable && existsSync("/usr/bin/prlimit") ? "/usr/bin/prlimit" : python,
		args:
			probe.rlimitSettable && existsSync("/usr/bin/prlimit")
				? [...prlimitArgs, python, ...pythonArgs]
				: [...pythonArgs],
		rung: probe.selectedRung,
		appliedRestrictions: restrictions,
		downgraded: true,
		downgradeReason: probe.downgradeReason,
	};
}

// ---------------------------------------------------------------------------
// Boundary facade
// ---------------------------------------------------------------------------

export interface SecurityBoundaryOptions {
	readonly allowlist?: Allowlist;
	readonly limits?: ResourceLimits;
	readonly ledger?: LedgerSink;
	readonly repoRoot?: string;
	readonly probe?: ProbeResult;
}

/**
 * The single object callers hold. Every deny path funnels through `deny()` so that
 * "declaration surface == enforcement surface": nothing can be declared forbidden without
 * simultaneously producing a ledger event and a thrown error.
 */
export class SecurityBoundary {
	readonly allowlist: Allowlist;
	readonly limits: ResourceLimits;
	readonly probe: ProbeResult;
	private readonly ledger: LedgerSink;
	private readonly repoRoot?: string;
	private denies = 0;

	constructor(options: SecurityBoundaryOptions = {}) {
		this.allowlist = options.allowlist ?? emptyAllowlist("boundary-default");
		this.limits = options.limits ?? DEFAULT_RESOURCE_LIMITS;
		this.ledger = options.ledger ?? (() => {});
		this.repoRoot = options.repoRoot;
		this.probe = options.probe ?? probeIsolation();
		this.emit("boundary.rung_selected", {
			rung: this.probe.selectedRung,
			landlockAvailable: this.probe.landlockAvailable,
			downgraded: this.probe.selectedRung !== "landlock",
			downgradeReason: this.probe.downgradeReason,
			allowlistVersion: this.allowlist.version,
		});
	}

	get denyCount(): number {
		return this.denies;
	}

	private emit(type: LedgerEventType, detail: Record<string, unknown>): void {
		this.ledger({ type, ts: new Date().toISOString(), detail });
	}

	/** Records a denial and throws. Crossing the boundary is a hard, loud event 鈥?never a warning. */
	private deny(decision: Decision, kind: "deny" | "limit" | "domain"): never {
		this.denies += 1;
		this.emit(kind === "limit" ? "security.limit_exceeded" : "security.deny", {
			list: decision.list,
			subject: decision.subject,
			reason: decision.reason,
			matched: decision.matched,
			verdict: "FAIL-KILL",
		});
		throw new SecurityBoundaryError(
			`security boundary denied ${decision.list} access to ${decision.subject} (${decision.reason})`,
			decision,
			kind,
		);
	}

	/** Throws unless the path is positively allowed for the requested access mode. */
	assertPath(candidate: string, access: "read" | "write" | "execute"): void {
		const decision = this.allowlist.checkPath(candidate, access, this.repoRoot);
		if (!decision.allowed) this.deny(decision, "deny");
	}

	/** Throws unless host:port is positively allowed. */
	assertEndpoint(host: string, port: number): void {
		const decision = this.allowlist.checkEndpoint(host, port);
		if (!decision.allowed) this.deny(decision, "deny");
	}

	/** Throws unless the command (and every argument) is positively allowed. */
	assertCommand(command: string, args: readonly string[] = []): void {
		const decision = this.allowlist.checkCommand(command, args);
		if (!decision.allowed) this.deny(decision, "deny");
	}

	/** Throws when a requested resource ceiling exceeds the configured or absolute maximum. */
	assertLimits(request: Partial<ResourceLimits>): void {
		const check = checkLimits(request, this.limits);
		if (!check.allowed) {
			this.deny(
				{
					allowed: false,
					list: "command",
					subject: `${String(check.field)}=${String(check.requested)}`,
					reason: check.reason,
					matched: check.ceiling === undefined ? undefined : `ceiling=${check.ceiling}`,
				},
				"limit",
			);
		}
	}

	/** Non-throwing variant for callers that need a verdict rather than an exception. */
	evaluatePath(candidate: string, access: "read" | "write" | "execute"): Decision {
		return this.allowlist.checkPath(candidate, access, this.repoRoot);
	}

	/** Builds the wrapped kernel argv and records the applied restrictions in the ledger. */
	planKernelSpawn(python: string, pythonArgs: readonly string[], allowNetwork = false): SpawnPlan {
		const plan = wrapKernelSpawn(python, pythonArgs, {
			allowlist: this.allowlist,
			limits: this.limits,
			probe: this.probe,
			allowNetwork,
		});
		this.emit("boundary.probe", {
			rung: plan.rung,
			downgraded: plan.downgraded,
			downgradeReason: plan.downgradeReason,
			restrictions: plan.appliedRestrictions,
		});
		return plan;
	}

	/** Emits an arbitrary boundary event (used by the domain proxy and git-snapshot modules). */
	record(type: LedgerEventType, detail: Record<string, unknown>): void {
		this.emit(type, detail);
	}
}

/**
 * K3 implant · W1-T1 · installed-boundary registry (single arming point).
 *
 * COMPONENT TRIPLE (verification_kernel.md §4.5.10)
 * - Reason to exist : the construction point (A2) and the dispatch point (A1) live in two upstream
 *                     files; both need to reach the same installed boundary without either file
 *                     importing session state. One tiny registry keeps the upstream diff to two
 *                     one-line call sites, which is what makes the implant independently removable.
 * - Axiom binding   : Axiom 5 (environment layer), Axiom 8 (minimal upstream conflict surface, J3).
 * - Deprecation     : replaceable by direct injection once K3 owns the session constructor; the
 *                     "one arming point, no agent-reachable disarm" property is not deprecable.
 *
 * NOT A SETTINGS SURFACE: arming happens only from `installK3SecurityBoundary()`, which is called
 * by K3 harness code. There is no environment variable, CLI flag, or settings key that reaches it,
 * and nothing inside the kernel's Python namespace can call `clearK3SecurityBoundary` (it exists in
 * the harness-side Node module graph only). Contrast with the pi sandbox example's `--no-sandbox`.
 */

import type { HostRequestHandlers } from "../../core/kernel/index.js";
import type { SecurityBoundary } from "./boundary.js";
import { armDispatchAssertion, disarmDispatchAssertion } from "./dispatch-assert.js";
import { DOMAIN_REGISTRY, type DomainSpec, guardHandlers } from "./domain-guard.js";

interface InstalledState {
	readonly boundary: SecurityBoundary;
	readonly registry: Readonly<Record<string, DomainSpec>>;
}

let installed: InstalledState | undefined;

/** Arms both attachment points. Idempotent per boundary instance. */
export function registerK3SecurityBoundary(
	boundary: SecurityBoundary,
	registry: Readonly<Record<string, DomainSpec>> = DOMAIN_REGISTRY,
): void {
	installed = { boundary, registry };
	armDispatchAssertion((type) => boundary.record("domain.deny", { type, reason: "unguarded_handler_at_dispatch" }));
}

/** Test-teardown seam; not reachable from the kernel process. */
export function clearK3SecurityBoundary(): void {
	installed = undefined;
	disarmDispatchAssertion();
}

export function getK3SecurityBoundary(): SecurityBoundary | undefined {
	return installed?.boundary;
}

/**
 * Attachment point A2 hook. Identity when the boundary is not installed, so upstream behaviour is
 * bit-identical with the implant removed; a full domain-guarded table when it is.
 */
export function applyK3DomainGuard(handlers: HostRequestHandlers): HostRequestHandlers {
	if (!installed) return handlers;
	const {
		handlers: guarded,
		guarded: wrapped,
		denied,
	} = guardHandlers(handlers, installed.boundary, installed.registry);
	installed.boundary.record("domain.call", {
		phase: "registration",
		guardedTypes: wrapped.length,
		deniedTypes: denied,
	});
	return guarded;
}

import { copyFileSync, existsSync, mkdirSync } from "node:fs";
import { basename, join, resolve } from "node:path";
import type { AgentSession } from "./agent-session.js";
import type { AgentSessionRuntimeConfig } from "./agent-session-config.js";
import type {
	AgentSessionCreationOptions,
	AgentSessionRuntimeDiagnostic,
	AgentSessionServices,
} from "./agent-session-services.js";
import { flushAgentTraceUpload } from "./agent-traces.js";
import { isNoModelsAvailableMessage } from "./auth-guidance.js";
import type { ReplacedSessionContext, SessionShutdownEvent, SessionStartEvent } from "./extensions/index.js";
import { emitSessionShutdownEvent } from "./extensions/runner.js";
import type { CreateRlmSubagentRuntimeOptions, RlmSubagentRuntime, SubagentRuntimeHost } from "./rlm-runtime.js";
import type { CreateAgentSessionResult } from "./sdk.js";
import { assertSessionCwdExists } from "./session-cwd.js";
import { SessionImportFileNotFoundError } from "./session-import-errors.js";
import { acquireSessionLease, canonicalSessionPath, type SessionLease } from "./session-lease.js";
import { SessionManager } from "./session-manager.js";

export { SessionImportFileNotFoundError } from "./session-import-errors.js";

/**
 * Result returned by runtime creation.
 *
 * The caller gets the created session, its cwd-bound services, and all
 * diagnostics collected during setup.
 */
export interface CreateAgentSessionRuntimeResult extends CreateAgentSessionResult {
	services: AgentSessionServices;
	diagnostics: AgentSessionRuntimeDiagnostic[];
}

/**
 * Creates a full runtime for a target cwd and session manager.
 *
 * The factory closes over process-global fixed inputs, recreates cwd-bound
 * services for the effective cwd, resolves session options against those
 * services, and finally creates the AgentSession.
 */
export type CreateAgentSessionRuntimeFactory = (options: {
	cwd: string;
	agentDir: string;
	sessionManager: SessionManager;
	sessionStartEvent?: SessionStartEvent;
	sessionConfig?: AgentSessionRuntimeConfig;
	sessionOptions?: AgentSessionCreationOptions;
}) => Promise<CreateAgentSessionRuntimeResult>;

export type AgentSessionRuntimeKind = "top-level" | "subagent";

export interface AgentSessionRuntimeMetadata {
	kind: AgentSessionRuntimeKind;
	createdAt: number;
	parentActiveSessionId?: string;
	parentSessionId?: string;
	parentSessionFile?: string;
	rlmChildId?: string;
	rlmParentNodeId?: string;
	/** Runtime restored from an already-persisted completed registry entry. */
	rehydratedCompleted?: boolean;
	prompt?: string;
	/** Source of the IPython cell that spawned this subagent, for display. */
	spawnCode?: string;
	sessionDir?: string;
}

function extractUserMessageText(content: string | Array<{ type: string; text?: string }>): string {
	if (typeof content === "string") {
		return content;
	}

	return content
		.filter((part): part is { type: "text"; text: string } => part.type === "text" && typeof part.text === "string")
		.map((part) => part.text)
		.join("");
}

/**
 * Owns the current AgentSession plus its cwd-bound services.
 *
 * Session replacement methods tear down the current runtime first, then create
 * and apply the next runtime. If creation fails, the error is propagated to the
 * caller. The caller is responsible for user-facing error handling.
 */
export class AgentSessionRuntime implements SubagentRuntimeHost {
	private rebindSession?: (session: AgentSession) => Promise<void>;
	private readonly sessionReplacedListeners = new Set<(session: AgentSession) => void | Promise<void>>();
	private runtimeEnvScope?: <T>(fn: () => Promise<T>) => Promise<T>;
	private beforeSessionInvalidate?: () => void;
	private subagentRuntimeHost?: SubagentRuntimeHost;
	private subagentRuntimes = new Map<string, AgentSessionRuntime>();
	private disposePromise?: Promise<void>;

	constructor(
		private _session: AgentSession,
		private _services: AgentSessionServices,
		private readonly createRuntime: CreateAgentSessionRuntimeFactory,
		private _diagnostics: AgentSessionRuntimeDiagnostic[] = [],
		private _modelFallbackMessage?: string,
		private readonly sessionConfig?: AgentSessionRuntimeConfig,
		private readonly _metadata: AgentSessionRuntimeMetadata = {
			kind: "top-level",
			createdAt: Date.now(),
		},
		private _sessionLease?: SessionLease,
	) {
		this.bindRuntimeHost();
	}

	get services(): AgentSessionServices {
		return this._services;
	}

	get session(): AgentSession {
		return this._session;
	}

	get cwd(): string {
		return this._services.cwd;
	}

	get diagnostics(): readonly AgentSessionRuntimeDiagnostic[] {
		return this._diagnostics;
	}

	get modelFallbackMessage(): string | undefined {
		// The "no models available" warning describes session state, not a
		// startup event: once the session gains a model (set_model, /login,
		// onboarding), the stored snapshot is stale and must not reach clients.
		if (isNoModelsAvailableMessage(this._modelFallbackMessage) && this._session.model) {
			return undefined;
		}
		return this._modelFallbackMessage;
	}

	get metadata(): AgentSessionRuntimeMetadata {
		return { ...this._metadata };
	}

	get runtimeConfig(): AgentSessionRuntimeConfig | undefined {
		return this.sessionConfig ? { ...this.sessionConfig } : undefined;
	}

	setRebindSession(rebindSession?: (session: AgentSession) => Promise<void>): void {
		this.rebindSession = rebindSession;
	}

	onSessionReplaced(listener: (session: AgentSession) => void | Promise<void>): () => void {
		this.sessionReplacedListeners.add(listener);
		return () => this.sessionReplacedListeners.delete(listener);
	}

	/**
	 * Host-installed scope wrapping every runtime rebuild (new/switch/fork/
	 * import and subagent creation), during which extensions re-load. The
	 * daemon uses it to apply the session's client env for load-time captures.
	 */
	setRuntimeEnvScope(scope?: <T>(fn: () => Promise<T>) => Promise<T>): void {
		this.runtimeEnvScope = scope;
	}

	private scopedBuild<T>(fn: () => Promise<T>): Promise<T> {
		return this.runtimeEnvScope ? this.runtimeEnvScope(fn) : fn();
	}

	setSubagentRuntimeHost(host?: SubagentRuntimeHost): void {
		this.subagentRuntimeHost = host;
		this.bindRuntimeHost();
	}

	/**
	 * Set a synchronous callback that runs after `session_shutdown` handlers finish
	 * but before the current session is invalidated.
	 *
	 * This is for host-owned UI teardown that must not yield to the event loop,
	 * such as detaching extension-provided TUI components before the old extension
	 * context becomes stale.
	 */
	setBeforeSessionInvalidate(beforeSessionInvalidate?: () => void): void {
		this.beforeSessionInvalidate = beforeSessionInvalidate;
	}

	private async emitBeforeSwitch(
		reason: "new" | "resume",
		targetSessionFile?: string,
	): Promise<{ cancelled: boolean }> {
		const runner = this.session.extensionRunner;
		if (!runner.hasHandlers("session_before_switch")) {
			return { cancelled: false };
		}

		const result = await runner.emit({
			type: "session_before_switch",
			reason,
			targetSessionFile,
		});
		return { cancelled: result?.cancel === true };
	}

	private async emitBeforeFork(
		entryId: string,
		options: { position: "before" | "at" },
	): Promise<{ cancelled: boolean }> {
		const runner = this.session.extensionRunner;
		if (!runner.hasHandlers("session_before_fork")) {
			return { cancelled: false };
		}

		const result = await runner.emit({
			type: "session_before_fork",
			entryId,
			...options,
		});
		return { cancelled: result?.cancel === true };
	}

	private async teardownCurrent(reason: SessionShutdownEvent["reason"], targetSessionFile?: string): Promise<void> {
		await emitSessionShutdownEvent(this.session.extensionRunner, {
			type: "session_shutdown",
			reason,
			targetSessionFile,
		});
		await flushAgentTraceUpload(this.session.sessionManager).catch(() => undefined);
		this.beforeSessionInvalidate?.();
		// Await the kernel's final snapshot flush before invalidating the session.
		await this.session.disposeAsync();
		await this.disposeHostedSubagentRuntimes();
	}

	private bindRuntimeHost(): void {
		this._session.setSubagentRuntimeHost(this.subagentRuntimeHost ?? this);
	}

	private apply(result: CreateAgentSessionRuntimeResult): void {
		this._session = result.session;
		this._services = result.services;
		this._diagnostics = result.diagnostics;
		this._modelFallbackMessage = result.modelFallbackMessage;
		this.bindRuntimeHost();
	}

	private acquireReplacementLease(sessionPath: string | undefined): SessionLease | undefined {
		if (sessionPath && this._sessionLease?.sessionPath === canonicalSessionPath(sessionPath)) {
			return this._sessionLease;
		}
		return acquireSessionLease(sessionPath, this.services.agentDir);
	}

	private releaseUncommittedLease(lease: SessionLease | undefined): void {
		if (lease !== this._sessionLease) {
			lease?.release();
		}
	}

	private releaseSessionLease(): void {
		this._sessionLease?.release();
		this._sessionLease = undefined;
	}

	private commitReplacementLease(lease: SessionLease | undefined): void {
		if (lease === this._sessionLease) {
			return;
		}
		const previous = this._sessionLease;
		this._sessionLease = lease;
		previous?.release();
	}

	private async buildAndApplyReplacement(
		build: () => Promise<CreateAgentSessionRuntimeResult>,
		lease: SessionLease | undefined,
	): Promise<void> {
		let result: CreateAgentSessionRuntimeResult;
		try {
			result = await build();
		} catch (error) {
			this.releaseUncommittedLease(lease);
			throw error;
		}
		this.apply(result);
		this.commitReplacementLease(lease);
	}

	private async teardownForReplacement(
		reason: SessionShutdownEvent["reason"],
		targetSessionFile: string | undefined,
		lease: SessionLease | undefined,
	): Promise<void> {
		try {
			await this.teardownCurrent(reason, targetSessionFile);
		} catch (error) {
			this.releaseUncommittedLease(lease);
			throw error;
		}
	}

	private async disposeSubagentRuntimes(): Promise<void> {
		const runtimes = [...this.subagentRuntimes.values()];
		this.subagentRuntimes.clear();
		let disposeError: unknown;
		for (const runtime of runtimes) {
			try {
				await runtime.dispose();
			} catch (error) {
				disposeError ??= error;
			}
		}
		if (disposeError) {
			throw disposeError;
		}
	}

	private async disposeHostedSubagentRuntimes(): Promise<void> {
		let disposeError: unknown;
		try {
			await this.subagentRuntimeHost?.disposeRlmSubagentRuntimes?.();
		} catch (error) {
			disposeError ??= error;
		}
		try {
			await this.disposeSubagentRuntimes();
		} catch (error) {
			disposeError ??= error;
		}
		if (disposeError) {
			throw disposeError;
		}
	}

	listSubagentRuntimes(): readonly AgentSessionRuntime[] {
		return [...this.subagentRuntimes.values()];
	}

	async createRlmSubagentRuntime(options: CreateRlmSubagentRuntimeOptions): Promise<RlmSubagentRuntime> {
		const sessionManager = SessionManager.create(options.parentSession.sessionManager.getCwd(), options.sessionDir);
		if (options.parentSession.sessionFile) {
			sessionManager.newSession({
				parentSession: options.parentSession.sessionFile,
				rlmDepth: options.rlmDepth,
			});
		}
		const runtime = await this.scopedBuild(() =>
			createAgentSessionRuntime(this.createRuntime, {
				cwd: sessionManager.getCwd(),
				agentDir: this.services.agentDir,
				sessionManager,
				sessionStartEvent: { type: "session_start", reason: "startup" },
				sessionConfig: this.sessionConfig,
				sessionOptions: {
					model: options.model,
					thinkingLevel: options.thinkingLevel,
					serviceTier: options.serviceTier,
					scopedModels: options.scopedModels,
					initialActiveToolNames: options.activeToolNames,
					allowedToolNames: options.allowedToolNames,
					customTools: options.customTools,
					includeGoals: options.includeGoals,
					includeCompactSkill: options.includeCompactSkill,
					rlmDepth: options.rlmDepth,
					rlmMaxDepth: options.rlmMaxDepth,
					rlmSessionDir: options.sessionDir,
					rlmParentNodeId: options.rlmParentNodeId,
					rlmParentAgent: options.parentSession.sessionName ?? options.parentSession.sessionId,
				},
				runtimeMetadata: {
					kind: "subagent",
					createdAt: Date.now(),
					parentSessionId: options.parentSession.sessionId,
					parentSessionFile: options.parentSession.sessionFile,
					rlmChildId: options.id,
					rlmParentNodeId: options.rlmParentNodeId,
					prompt: options.prompt,
					spawnCode: options.spawnCode,
					sessionDir: options.sessionDir,
				},
			}),
		);
		this.subagentRuntimes.set(options.id, runtime);
		try {
			await runtime.session.bindExtensions({});
			if (options.parentSession.getRlmChildRunStatus(options.id) === "cancelled") {
				throw new Error("RLM subagent startup was cancelled");
			}
			if (runtime.session.sessionName !== options.sessionName) {
				runtime.session.setSessionName(options.sessionName);
			}
			options.onSessionPublished?.(runtime.session);
		} catch (error) {
			this.subagentRuntimes.delete(options.id);
			await runtime.dispose();
			throw error;
		}
		return runtime;
	}

	async deleteRlmSubagentRuntime(childId: string, session: AgentSession): Promise<void> {
		const runtime = this.subagentRuntimes.get(childId);
		if (!runtime) {
			await session.disposeAsync();
			return;
		}
		this.subagentRuntimes.delete(childId);
		const shouldDisposeStaleSession = runtime.session !== session;
		try {
			await runtime.dispose();
		} finally {
			if (shouldDisposeStaleSession) {
				await session.disposeAsync();
			}
		}
	}

	private async finishSessionReplacement(withSession?: (ctx: ReplacedSessionContext) => Promise<void>): Promise<void> {
		if (this.rebindSession) {
			await this.rebindSession(this.session);
		}
		for (const listener of this.sessionReplacedListeners) {
			await listener(this.session);
		}
		if (withSession) {
			await withSession(this.session.createReplacedSessionContext());
		}
	}

	async switchSession(
		sessionPath: string,
		options?: {
			cwdOverride?: string;
			withSession?: (ctx: ReplacedSessionContext) => Promise<void>;
		},
	): Promise<{ cancelled: boolean }> {
		const beforeResult = await this.emitBeforeSwitch("resume", sessionPath);
		if (beforeResult.cancelled) {
			return beforeResult;
		}

		const previousSessionFile = this.session.sessionFile;
		const lease = this.acquireReplacementLease(sessionPath);
		let sessionManager: SessionManager;
		try {
			sessionManager = SessionManager.open(sessionPath, undefined, options?.cwdOverride);
			assertSessionCwdExists(sessionManager, this.cwd);
		} catch (error) {
			this.releaseUncommittedLease(lease);
			throw error;
		}
		await this.teardownForReplacement("resume", sessionManager.getSessionFile(), lease);
		await this.buildAndApplyReplacement(
			() =>
				this.scopedBuild(() =>
					this.createRuntime({
						cwd: sessionManager.getCwd(),
						agentDir: this.services.agentDir,
						sessionManager,
						sessionStartEvent: {
							type: "session_start",
							reason: "resume",
							previousSessionFile,
						},
						sessionConfig: this.sessionConfig,
					}),
				),
			lease,
		);
		await this.finishSessionReplacement(options?.withSession);
		return { cancelled: false };
	}

	async newSession(options?: {
		parentSession?: string;
		setup?: (sessionManager: SessionManager) => Promise<void>;
		withSession?: (ctx: ReplacedSessionContext) => Promise<void>;
	}): Promise<{ cancelled: boolean }> {
		const beforeResult = await this.emitBeforeSwitch("new");
		if (beforeResult.cancelled) {
			return beforeResult;
		}

		const previousSessionFile = this.session.sessionFile;
		const sessionDir = this.session.sessionManager.getSessionDir();
		const sessionManager = SessionManager.create(this.cwd, sessionDir);
		if (options?.parentSession) {
			sessionManager.newSession({
				parentSession: options.parentSession,
				rlmDepth: this.session.sessionManager.getHeader()?.rlmDepth ?? this.session.rlmDepth,
			});
		}
		const lease = this.acquireReplacementLease(sessionManager.getSessionFile());

		await this.teardownForReplacement("new", sessionManager.getSessionFile(), lease);
		await this.buildAndApplyReplacement(
			() =>
				this.scopedBuild(() =>
					this.createRuntime({
						cwd: this.cwd,
						agentDir: this.services.agentDir,
						sessionManager,
						sessionStartEvent: {
							type: "session_start",
							reason: "new",
							previousSessionFile,
						},
						sessionConfig: this.sessionConfig,
					}),
				),
			lease,
		);
		if (options?.setup) {
			await options.setup(this.session.sessionManager);
			this.session.agent.state.messages = this.session.sessionManager.buildSessionContext().messages;
		}
		await this.finishSessionReplacement(options?.withSession);
		return { cancelled: false };
	}

	async fork(
		entryId: string,
		options?: {
			position?: "before" | "at";
			withSession?: (ctx: ReplacedSessionContext) => Promise<void>;
		},
	): Promise<{ cancelled: boolean; selectedText?: string }> {
		const position = options?.position ?? "before";
		const beforeResult = await this.emitBeforeFork(entryId, { position });
		if (beforeResult.cancelled) {
			return { cancelled: true };
		}
		let targetLeafId: string | null;
		let selectedText: string | undefined;

		const selectedEntry = this.session.sessionManager.getEntry(entryId);
		if (!selectedEntry) {
			throw new Error("Invalid entry ID for forking");
		}

		if (position === "at") {
			targetLeafId = selectedEntry.id;
		} else {
			if (selectedEntry.type !== "message" || selectedEntry.message.role !== "user") {
				throw new Error("Invalid entry ID for forking");
			}
			targetLeafId = selectedEntry.parentId;
			selectedText = extractUserMessageText(selectedEntry.message.content);
		}

		const previousSessionFile = this.session.sessionFile;
		if (this.session.sessionManager.isPersisted()) {
			const currentSessionFile = this.session.sessionFile;
			if (!currentSessionFile) {
				throw new Error("Persisted session is missing a session file");
			}
			const sessionDir = this.session.sessionManager.getSessionDir();
			if (!targetLeafId) {
				const sourceHeader = this.session.sessionManager.getHeader();
				const sessionManager = SessionManager.create(this.cwd, sessionDir);
				sessionManager.newSession({
					parentSession: currentSessionFile,
					rlmDepth: sourceHeader?.rlmDepth ?? this.session.rlmDepth,
				});
				const lease = this.acquireReplacementLease(sessionManager.getSessionFile());
				await this.teardownForReplacement("fork", sessionManager.getSessionFile(), lease);
				await this.buildAndApplyReplacement(
					() =>
						this.scopedBuild(() =>
							this.createRuntime({
								cwd: this.cwd,
								agentDir: this.services.agentDir,
								sessionManager,
								sessionStartEvent: {
									type: "session_start",
									reason: "fork",
									previousSessionFile,
								},
								sessionConfig: this.sessionConfig,
							}),
						),
					lease,
				);
				await this.finishSessionReplacement(options?.withSession);
				return { cancelled: false, selectedText };
			}

			const sourceManager = SessionManager.open(currentSessionFile, sessionDir);
			const forkedSessionPath = sourceManager.createBranchedSession(targetLeafId);
			if (!forkedSessionPath) {
				throw new Error("Failed to create forked session");
			}
			const sessionManager = SessionManager.open(forkedSessionPath, sessionDir);
			const lease = this.acquireReplacementLease(sessionManager.getSessionFile());
			await this.teardownForReplacement("fork", sessionManager.getSessionFile(), lease);
			await this.buildAndApplyReplacement(
				() =>
					this.scopedBuild(() =>
						this.createRuntime({
							cwd: sessionManager.getCwd(),
							agentDir: this.services.agentDir,
							sessionManager,
							sessionStartEvent: {
								type: "session_start",
								reason: "fork",
								previousSessionFile,
							},
							sessionConfig: this.sessionConfig,
						}),
					),
				lease,
			);
			await this.finishSessionReplacement(options?.withSession);
			return { cancelled: false, selectedText };
		}

		const sessionManager = this.session.sessionManager;
		if (!targetLeafId) {
			const sourceHeader = sessionManager.getHeader();
			sessionManager.newSession({
				parentSession: this.session.sessionFile,
				rlmDepth: sourceHeader?.rlmDepth ?? this.session.rlmDepth,
			});
		} else {
			sessionManager.createBranchedSession(targetLeafId);
		}
		const lease = this.acquireReplacementLease(sessionManager.getSessionFile());
		await this.teardownForReplacement("fork", sessionManager.getSessionFile(), lease);
		await this.buildAndApplyReplacement(
			() =>
				this.scopedBuild(() =>
					this.createRuntime({
						cwd: this.cwd,
						agentDir: this.services.agentDir,
						sessionManager,
						sessionStartEvent: {
							type: "session_start",
							reason: "fork",
							previousSessionFile,
						},
						sessionConfig: this.sessionConfig,
					}),
				),
			lease,
		);
		await this.finishSessionReplacement(options?.withSession);
		return { cancelled: false, selectedText };
	}

	/**
	 * Import a session JSONL file and switch runtime state to the imported session.
	 *
	 * @returns `{ cancelled: true }` when cancelled by `session_before_switch`, otherwise `{ cancelled: false }`.
	 * @throws {SessionImportFileNotFoundError} When the input path does not exist.
	 * @throws {MissingSessionCwdError} When the imported session cwd cannot be resolved and no override is provided.
	 */
	async importFromJsonl(inputPath: string, cwdOverride?: string): Promise<{ cancelled: boolean }> {
		const resolvedPath = resolve(inputPath);
		if (!existsSync(resolvedPath)) {
			throw new SessionImportFileNotFoundError(resolvedPath);
		}

		const sessionDir = this.session.sessionManager.getSessionDir();
		if (!existsSync(sessionDir)) {
			mkdirSync(sessionDir, { recursive: true });
		}

		const destinationPath = join(sessionDir, basename(resolvedPath));
		const beforeResult = await this.emitBeforeSwitch("resume", destinationPath);
		if (beforeResult.cancelled) {
			return beforeResult;
		}

		const previousSessionFile = this.session.sessionFile;
		const lease = this.acquireReplacementLease(destinationPath);
		let sessionManager: SessionManager;
		try {
			if (resolve(destinationPath) !== resolvedPath) {
				copyFileSync(resolvedPath, destinationPath);
			}

			sessionManager = SessionManager.open(destinationPath, sessionDir, cwdOverride);
			assertSessionCwdExists(sessionManager, this.cwd);
		} catch (error) {
			this.releaseUncommittedLease(lease);
			throw error;
		}
		await this.teardownForReplacement("resume", sessionManager.getSessionFile(), lease);
		await this.buildAndApplyReplacement(
			() =>
				this.scopedBuild(() =>
					this.createRuntime({
						cwd: sessionManager.getCwd(),
						agentDir: this.services.agentDir,
						sessionManager,
						sessionStartEvent: {
							type: "session_start",
							reason: "resume",
							previousSessionFile,
						},
						sessionConfig: this.sessionConfig,
					}),
				),
			lease,
		);
		await this.finishSessionReplacement();
		return { cancelled: false };
	}

	private async disposeOnce(): Promise<void> {
		let disposeError: unknown;
		try {
			await emitSessionShutdownEvent(this.session.extensionRunner, {
				type: "session_shutdown",
				reason: "quit",
			});
		} catch (error) {
			disposeError ??= error;
		}
		try {
			await flushAgentTraceUpload(this.session.sessionManager);
		} catch (error) {
			disposeError ??= error;
		}
		try {
			this.beforeSessionInvalidate?.();
		} catch (error) {
			disposeError ??= error;
		}
		try {
			// Await the kernel's final snapshot flush before tearing the session down.
			await this.session.disposeAsync();
		} catch (error) {
			disposeError ??= error;
		}
		try {
			await this.disposeHostedSubagentRuntimes();
		} catch (error) {
			disposeError ??= error;
		}
		try {
			if (disposeError) {
				throw disposeError;
			}
		} finally {
			this.releaseSessionLease();
		}
	}

	async dispose(): Promise<void> {
		if (!this.disposePromise) {
			this.disposePromise = this.disposeOnce();
		}
		await this.disposePromise;
	}
}

/**
 * Create the initial runtime from a runtime factory and initial session target.
 *
 * The same factory is stored on the returned AgentSessionRuntime and reused for
 * later /new, resume, /fork, and import flows.
 */
export async function createAgentSessionRuntime(
	createRuntime: CreateAgentSessionRuntimeFactory,
	options: {
		cwd: string;
		agentDir: string;
		sessionManager: SessionManager;
		sessionStartEvent?: SessionStartEvent;
		sessionConfig?: AgentSessionRuntimeConfig;
		sessionOptions?: AgentSessionCreationOptions;
		runtimeMetadata?: AgentSessionRuntimeMetadata;
		sessionLease?: SessionLease;
	},
): Promise<AgentSessionRuntime> {
	const { sessionLease, ...runtimeOptions } = options;
	const lease =
		sessionLease ?? acquireSessionLease(runtimeOptions.sessionManager.getSessionFile(), runtimeOptions.agentDir);
	try {
		assertSessionCwdExists(runtimeOptions.sessionManager, runtimeOptions.cwd);
		const result = await createRuntime(runtimeOptions);
		return new AgentSessionRuntime(
			result.session,
			result.services,
			createRuntime,
			result.diagnostics,
			result.modelFallbackMessage,
			runtimeOptions.sessionConfig,
			runtimeOptions.runtimeMetadata,
			lease,
		);
	} catch (error) {
		lease?.release();
		throw error;
	}
}

